const containerFiles=document.getElementById("containerFilesID"),containerInfo=document.getElementById("containerInfoID"),volumeName=document.getElementById("volumeNameID"),usedSize=document.getElementById("usedSizeID"),totalSpace=document.getElementById("totalSpaceID"),containerSpinner=document.getElementById("containerSpinnerID"),colSize=document.getElementById("colSizeID"),formIndex=document.getElementById("formIndexID"),btnGetFileData=document.getElementById("btnGetFileDataID"),containerMessage=document.getElementById("containerMessageID");function formatSize(bytes){const units=["Bytes","KB","MB","GB","TB"];let index=0,size=parseInt(bytes);for(;size>=1024&&index<units.length-1;)size/=1024,index++;return`${size.toFixed(2)} ${units[index]}`}function getFTPData(){formIndex.checkValidity()?(containerSpinner.style.display="block",formData=new FormData(formIndex),urlsearchparams=new URLSearchParams(formData),urlsearchparams.set("index",parseInt(urlsearchparams.get("index"))-1),btnGetFileData.disabled=!0,containerSpinner.style.display="block",containerMessage.style.display="none",containerFiles.innerHTML="",fetch("/ftp_get_data",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlsearchparams.toString()}).then((response=>{if(response.ok)return response.text();throw new Error(response.status+" "+response.statusText)})).then((data=>{containerSpinner.style.display="none",containerMessage.innerHTML="",containerInfo.style.display="block";const params=new URLSearchParams(data),volume_name=params.get("volume_name"),used_bytes=parseInt(params.get("used_bytes")),total_bytes=parseInt(params.get("total_bytes")),bytes_rel=100*used_bytes/total_bytes;colSize.classList=bytes_rel<50?"cl bd bd-ss":bytes_rel<80?"cl bd bd-wg":"cl bd bd-dg",volumeName.innerHTML=volume_name,usedSize.innerHTML=formatSize(used_bytes),totalSpace.innerHTML=formatSize(total_bytes);const filenames=params.getAll("filename"),filesizes=params.getAll("filesize");filenames.forEach(((filename,index)=>{const filesize=filesizes[index],fileDiv=document.createElement("div");fileDiv.className="m-1",fileDiv.innerHTML=`\n            <div class="r">\n                <div class="cl cl-nw">${filename}</div>\n                <div class="cl cl-nw">${formatSize(filesize)}</div>\n                <div class="cl cl-nw">\n                    <div class="r j-c">\n                        <div class="btn btn-ss btn-i" onclick="DownloadFile('${filename}')">\n                            <i>&#8595;</i>\n                        </div>\n                    </div>\n                </div>\n            </div>\n        `,containerFiles.appendChild(fileDiv)})),btnGetFileData.disabled=!1})).catch((error=>{containerSpinner.style.display="none",containerMessage.style.display="block",containerMessage.className="bd bd-dg",containerMessage.innerHTML=error,btnGetFileData.disabled=!1}))):formIndex.reportValidity()}function DownloadFile(filename){urlEncodedData=new URLSearchParams,urlEncodedData.append("filename",filename),fetch("/ftp_get_file",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:urlEncodedData.toString()}).then((response=>{if(response.ok)return response.blob();throw new Error(response.status+" "+response.statusText)})).then((blob=>{const downloadUrl=URL.createObjectURL(blob),a=document.createElement("a");a.href=downloadUrl,a.download=filename,document.body.appendChild(a),a.click(),document.body.removeChild(a),URL.revokeObjectURL(downloadUrl)})).catch((error=>{containerSpinner.style.display="none",containerMessage.className="bd bd-dg",containerMessage.innerHTML=error}))}